==================== snapshot
{
 "type": "object",
 "additionalProperties": false,
 "required": [
  "schemaVersion",
  "projectId",
  "sourceInventory",
  "resolvedConfigDigest",
  "scopeDigest",
  "vcsDigest"
 ],
 "properties": {
  "schemaVersion": {
   "const": 2
  },
  "projectId": {
   "$ref": "#/$defs/ProjectId"
  },
  "sourceInventory": {
   "$ref": "#/$defs/source-inventory"
  },
  "resolvedConfigDigest": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "canonical-record",
    "record": {
     "bundle": "identity",
     "selector": "#/$defs/semantic-configuration"
    }
   }
  },
  "scopeDigest": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "canonical-record",
    "record": {
     "bundle": "identity",
     "selector": "#/$defs/scope-descriptor"
    }
   }
  },
  "vcsDigest": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "canonical-record",
    "record": {
     "bundle": "identity",
     "selector": "#/$defs/vcs-observation"
    }
   }
  }
 }
}
==================== plan
{
 "type": "object",
 "additionalProperties": false,
 "required": [
  "schemaVersion",
  "snapshotId",
  "capabilityManifestId",
  "semanticClosures",
  "analysisSpecDigest",
  "resolvedConfigDigest",
  "nativeContextDigests",
  "importIds",
  "policyDigest",
  "waiverDigest",
  "scopeDigest",
  "budget",
  "semanticGrantDigest",
  "capabilityManifestBytesDigest"
 ],
 "properties": {
  "schemaVersion": {
   "const": 2
  },
  "snapshotId": {
   "type": "string",
   "pattern": "^snapshot2:[0-9a-f]{64}(?![\\s\\S])"
  },
  "capabilityManifestId": {
   "$ref": "#/$defs/Hash",
   "x-opensip-digest": {
    "representation": "capability-manifest-id",
    "retention": "derived",
    "derivedFrom": "plan.capabilityManifestBytesDigest"
   }
  },
  "semanticClosures": {
   "type": "array",
   "maxItems": 128,
   "items": {
    "type": "string",
    "pattern": "^closure2:[0-9a-f]{64}(?![\\s\\S])"
   },
   "uniqueItems": true,
   "x-opensip-order": "canonical-set"
  },
  "analysisSpecDigest": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "canonical-record",
    "record": {
     "bundle": "identity",
     "selector": "#/$defs/analysis-spec"
    }
   }
  },
  "resolvedConfigDigest": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "canonical-record",
    "record": {
     "bundle": "identity",
     "selector": "#/$defs/semantic-configuration"
    }
   }
  },
  "nativeContextDigests": {
   "type": "array",
   "maxItems": 128,
   "items": {
    "type": "string",
    "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
    "x-opensip-digest": {
     "representation": "h-identity",
     "domainSet": "native-context"
    }
   },
   "uniqueItems": true,
   "x-opensip-order": "canonical-set"
  },
  "importIds": {
   "type": "array",
   "maxItems": 256,
   "items": {
    "type": "string",
    "pattern": "^import2:[0-9a-f]{64}(?![\\s\\S])"
   },
   "uniqueItems": true,
   "x-opensip-order": "canonical-set"
  },
  "policyDigest": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "canonical-record",
    "record": {
     "document": "workflows/schemas/policy-document.schema.json",
     "selector": "#/$defs/PolicyDocumentV1"
    }
   }
  },
  "waiverDigest": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "canonical-record",
    "record": {
     "document": "workflows/schemas/policy-document.schema.json",
     "selector": "#/$defs/WaiverSetV1"
    }
   }
  },
  "scopeDigest": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "canonical-record",
    "record": {
     "bundle": "identity",
     "selector": "#/$defs/scope-descriptor"
    }
   }
  },
  "budget": {
   "type": "object",
   "additionalProperties": false,
   "required": [
    "unit",
    "limit"
   ],
   "properties": {
    "unit": {
     "const": "work-units"
    },
    "limit": {
     "type": "integer",
     "minimum": 1,
     "maximum": 9007199254740991
    }
   },
   "description": "Equal, exactly and by type, to the analysis.budget of the committed resolved semantic configuration this Plan names (identity-and-evidence section 3 closure list). A legitimate override enters the resolved configuration first; neither committed place silently wins."
  },
  "semanticGrantDigest": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "canonical-record",
    "record": {
     "bundle": "identity",
     "selector": "#/$defs/semantic-grant"
    }
   }
  },
  "capabilityManifestBytesDigest": {
   "$ref": "#/$defs/Hash",
   "x-opensip-digest": {
    "representation": "raw-artifact",
    "artifact": "the exact committed CVE1 capability manifest artifact bytes"
   }
  }
 }
}
==================== fact
{
 "type": "object",
 "additionalProperties": false,
 "required": [
  "schemaVersion",
  "snapshotId",
  "relation",
  "resolution",
  "sourceUniverse",
  "targetUniverse",
  "producerClosure",
  "payloadSchemaDigest",
  "payloadDigest",
  "anchors",
  "confidenceMillionths"
 ],
 "properties": {
  "schemaVersion": {
   "const": 2
  },
  "snapshotId": {
   "type": "string",
   "pattern": "^snapshot2:[0-9a-f]{64}(?![\\s\\S])"
  },
  "relation": {
   "type": "string",
   "minLength": 1,
   "maxLength": 4096
  },
  "resolution": {
   "type": "string",
   "minLength": 1,
   "maxLength": 4096
  },
  "sourceUniverse": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "h-identity",
    "domainSet": "native-semantic-universe"
   }
  },
  "targetUniverse": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "h-identity",
    "domainSet": "native-semantic-universe"
   }
  },
  "producerClosure": {
   "type": "string",
   "pattern": "^closure2:[0-9a-f]{64}(?![\\s\\S])"
  },
  "payloadSchemaDigest": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "raw-artifact",
    "artifact": "the exact full bytes of foundation/relation-payload-schemas.v2.json, the registered relation payload schema document"
   }
  },
  "payloadDigest": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "canonical-record",
    "record": {
     "payloadClass": "relation",
     "keyedBy": [
      "relation"
     ],
     "schemaDigestField": "payloadSchemaDigest"
    }
   }
  },
  "anchors": {
   "type": "array",
   "maxItems": 100000,
   "uniqueItems": true,
   "items": {
    "type": "object",
    "additionalProperties": false,
    "required": [
     "path",
     "blobDigest",
     "startByte",
     "endByte"
    ],
    "properties": {
     "path": {
      "type": "string",
      "minLength": 1,
      "maxLength": 4096
     },
     "blobDigest": {
      "type": "string",
      "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
      "x-opensip-digest": {
       "representation": "raw-artifact",
       "artifact": "the exact retained source blob bytes named by path in the snapshot inventory"
      }
     },
     "startByte": {
      "type": "integer",
      "minimum": 0,
      "maximum": 18446744073709551615
     },
     "endByte": {
      "type": "integer",
      "minimum": 0,
      "maximum": 18446744073709551615
     }
    }
   },
   "x-opensip-order": "canonical-set"
  },
  "confidenceMillionths": {
   "type": "integer",
   "minimum": 0,
   "maximum": 1000000
  }
 }
}
==================== subject-scope
{
 "type": "object",
 "additionalProperties": false,
 "required": [
  "schemaVersion",
  "snapshotId",
  "sourceUniverse",
  "targetUniverse",
  "relation",
  "resolution",
  "enumeratorClosure",
  "subjects"
 ],
 "properties": {
  "schemaVersion": {
   "const": 2
  },
  "snapshotId": {
   "type": "string",
   "pattern": "^snapshot2:[0-9a-f]{64}(?![\\s\\S])"
  },
  "sourceUniverse": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "h-identity",
    "domainSet": "native-semantic-universe"
   }
  },
  "targetUniverse": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "h-identity",
    "domainSet": "native-semantic-universe"
   }
  },
  "relation": {
   "type": "string",
   "minLength": 1,
   "maxLength": 4096
  },
  "resolution": {
   "type": "string",
   "minLength": 1,
   "maxLength": 4096
  },
  "enumeratorClosure": {
   "type": "string",
   "pattern": "^closure2:[0-9a-f]{64}(?![\\s\\S])",
   "description": "The Plan-selected closure that enumerated this scope. Its kind must be 'provider': enumeration is a native provider act, and no 'enumerator' kind is minted for it. The closure must also be a member of plan.semanticClosures, so the enumerator is one the Plan selected."
  },
  "subjects": {
   "type": "array",
   "maxItems": 100000,
   "items": {
    "type": "string",
    "minLength": 1,
    "maxLength": 4096
   },
   "uniqueItems": true,
   "x-opensip-order": "canonical-set"
  }
 }
}
