==================== proof-bundle
{
 "type": "object",
 "additionalProperties": false,
 "required": [
  "schemaVersion",
  "planId",
  "executionPlanId",
  "evaluatorClosure",
  "ruleProgramDigest",
  "evaluationInputRefs",
  "predicateProofs",
  "findingIds",
  "verdict"
 ],
 "properties": {
  "schemaVersion": {
   "const": 2
  },
  "planId": {
   "type": "string",
   "pattern": "^plan2:[0-9a-f]{64}(?![\\s\\S])"
  },
  "executionPlanId": {
   "type": "string",
   "pattern": "^exec-plan2:[0-9a-f]{64}(?![\\s\\S])"
  },
  "evaluatorClosure": {
   "type": "string",
   "pattern": "^closure2:[0-9a-f]{64}(?![\\s\\S])"
  },
  "ruleProgramDigest": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "canonical-record",
    "record": {
     "document": "workflows/schemas/policy-document.schema.json",
     "selector": "#/$defs/RuleProgramV1"
    }
   }
  },
  "evaluationInputRefs": {
   "type": "array",
   "maxItems": 100000,
   "items": {
    "$ref": "#/$defs/ProofInputRef"
   },
   "uniqueItems": true,
   "x-opensip-order": "canonical-set"
  },
  "predicateProofs": {
   "type": "array",
   "maxItems": 100000,
   "items": {
    "type": "object",
    "additionalProperties": false,
    "required": [
     "ruleId",
     "subjectId",
     "predicateId",
     "operation",
     "inputRefs",
     "scopeIds",
     "value",
     "witnessDigest"
    ],
    "properties": {
     "ruleId": {
      "type": "string",
      "minLength": 1,
      "maxLength": 4096
     },
     "subjectId": {
      "type": "string",
      "minLength": 1,
      "maxLength": 4096
     },
     "predicateId": {
      "type": "string",
      "minLength": 1,
      "maxLength": 4096
     },
     "operation": {
      "type": "string",
      "enum": [
       "exists",
       "none",
       "count-at-most",
       "all-covered",
       "and",
       "or",
       "not"
      ]
     },
     "inputRefs": {
      "type": "array",
      "maxItems": 100000,
      "items": {
       "$ref": "#/$defs/ProofInputRef"
      },
      "uniqueItems": true,
      "x-opensip-order": "canonical-set"
     },
     "scopeIds": {
      "type": "array",
      "maxItems": 100000,
      "items": {
       "type": "string",
       "pattern": "^scope2:[0-9a-f]{64}(?![\\s\\S])"
      },
      "uniqueItems": true,
      "x-opensip-order": "canonical-set"
     },
     "value": {
      "type": "string",
      "enum": [
       "true",
       "false",
       "indeterminate"
      ]
     },
     "witnessDigest": {
      "type": "string",
      "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
      "x-opensip-digest": {
       "representation": "canonical-record",
       "record": {
        "bundle": "identity",
        "selector": "#/$defs/predicate-witness"
       }
      }
     }
    }
   },
   "uniqueItems": true,
   "x-opensip-order": "predicate"
  },
  "findingIds": {
   "type": "array",
   "maxItems": 100000,
   "items": {
    "type": "string",
    "pattern": "^finding2:[0-9a-f]{64}(?![\\s\\S])"
   },
   "uniqueItems": true,
   "x-opensip-order": "canonical-set"
  },
  "verdict": {
   "type": "string",
   "enum": [
    "pass",
    "fail",
    "indeterminate"
   ]
  }
 }
}

==================== closure
{
 "type": "object",
 "additionalProperties": false,
 "required": [
  "schemaVersion",
  "kind",
  "manifestDigest",
  "tree",
  "semanticVersion",
  "protocolMajor",
  "platform"
 ],
 "properties": {
  "schemaVersion": {
   "const": 2
  },
  "kind": {
   "type": "string",
   "enum": [
    "provider",
    "evaluator",
    "detector",
    "toolchain",
    "stdlib",
    "rust-dev-llvm",
    "grammar",
    "adapter"
   ]
  },
  "manifestDigest": {
