   "level": "L1-lexical",
   "normalises": "insignificant whitespace and line endings",
   "use": "DEFAULT for exact-duplicate detection"
  },
  {
   "level": "L2-comment-insensitive",
   "normalises": "L1 plus non-directive comments",
   "use": "opt-in"
  },
  {
   "level": "L3-identifier-insensitive",
   "normalises": "L2 plus consistent renaming of LOCAL bindings",
   "use": "opt-in; near-duplicate only"
  }
 ],
 "defaultLevel": "L1-lexical",
 "rules": [
  {
   "id": "BH-1",
   "rule": "Each level is separately versioned. Changing L2's comment grammar does not touch L1 identities."
  },
  {
   "id": "BH-2",
   "rule": "The level and its version are part of the fact's identity and enter the derivation key. Two levels are two facts, never one fact computed differently."
  },
  {
   "id": "BH-3",
   "rule": "A finding records the level that produced it. Comparing a baseline entry pinned to L1 against an L2 result is a typed mismatch, not a diff."
  },
  {
   "id": "BH-4",
   "rule": "Adding a level is schema-additive and changes no existing identity."
  },
  {
   "id": "BH-5",
   "rule": "Changing an EXISTING level's algorithm requires the custody transition protocol below. There is no migrator that can invent the old identity from the new one."
  },
  {
   "id": "BH-6",
   "rule": "The L0 span LOCATION is retrievable for any finding at any level. Retrieving its BYTES is a separate, retention-governed act (B-FI-04)."
  }
 ]
