_CAUSE_TABLE = {
    # native-evidence S10 deficiency/cause table
    "input-closure-incomplete": {
        "carrier": "nativeCause", "required": True,
        "values": ["missing-dependency-source", "lockfile-missing",
                   "source-replacement-outside-snapshot",
                   "generated-output-unavailable", "generated-file-missing",
                   "generated-file-out-of-bounds", "no-program-unit",
                   "node-modules-outside-read-set", "config-flag-stripped",
                   "body-language-ownership-missing",
                   "body-language-owner-unenumerated",
                   "body-language-owner-ambiguous"]},
    "resolution-incomplete": {"carrier": "resolutionCompleteness", "required": False},
    "external-consumers-unknown": {"carrier": "closedWorld.exportsClosed",
                                   "required": False},
    "derivation-policy-unmet": {"carrier": "derivationKinds", "required": False},
    "provider-unavailable": {"carrier": "nativeCause", "required": False,
                             "values": ["capability-missing", "linker-unavailable"]},
    "language-tier-unsupported": {"carrier": "nativeCause", "required": True,
                                  "values": ["capability-missing"]},
    "budget-exhausted": {"carrier": "stageTerminal", "required": False},
    "confidence-floor-unmet": {"carrier": "none", "required": False},
    "required-relation-missing": {"carrier": "none", "required": False},
}


def _docname(document):
    m = {"native/native-evidence.schemas.v2.json": "native",
         "foundation/relation-payload-schemas.v2.json": "relation",
         "foundation/identity-schemas.v2.json": "identity",
         "workflows/schemas/policy-document.schema.json": "policy-document",
         "workflows/schemas/imported-evidence.schema.json": "imported-evidence",
         "workflows/schemas/test-execution.schema.json": "test-execution",
         "foundation/import-source-context.schema.json": "import-source-context"}
    return m[document]


def _config_node_kind(path):
    """native S2.2 / x-opensip-config-node-kind-law: exact basename table."""
    base = path.rsplit("/", 1)[-1]
    if base == "tsconfig.json":
        return "tsconfig"
    if base == "jsconfig.json":
        return "jsconfig"
    return "other"


def _fold(n):
    """The published fold is Unicode Default Case Conversion toLowercase(X).
    Every lib name in the pinned compiler's option vocabulary is ASCII, where
    the three candidate operations coincide; Python's str.lower() implements
    the full, non-tailored default lowercase mapping (including the U+0130 and
    Final_Sigma cases the contract's discriminator table names)."""
    return n.lower()


def _parse_body_frame(fr):
    i = 0
    comps = []
    try:
        for _ in range(5):
            n = fr[i]
            i += 1
            comps.append(fr[i:i + n])
            i += n
